INSERT INTO auth.users(id,email_confirmed_at) SELECT ('79000000-0000-4000-8000-00000000000'||n)::uuid,now() FROM generate_series(1,6)n;
INSERT INTO public.profiles(id,username,display_name,role) SELECT id,'dating'||right(id::text,1),'Dating fixture',CASE WHEN right(id::text,1)='6' THEN 'admin' ELSE 'user' END FROM auth.users;
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000001',false);
SELECT public.dating_save_profile(extract(year FROM current_date)::int-32,'man',ARRAY['woman'],25,35,ARRAY['coffee'],(current_date-interval '32 years')::date);
SELECT set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000002',false);
SELECT public.dating_save_profile(extract(year FROM current_date)::int-30,'woman',ARRAY['man'],30,40,ARRAY['walks'],(current_date-interval '30 years')::date);
SELECT set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000003',false);
SELECT public.dating_save_profile(extract(year FROM current_date)::int-20,'woman',ARRAY['man'],18,99,'{}',(current_date-interval '20 years')::date);
SELECT set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000004',false);
DO $$ BEGIN
 BEGIN PERFORM public.dating_save_profile(extract(year FROM current_date)::int-16,'man',ARRAY['woman'],18,30); RAISE EXCEPTION 'underage accepted'; EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'adult_only' THEN RAISE; END IF; END;
 BEGIN PERFORM public.dating_save_profile(extract(year FROM current_date)::int-18,'man',ARRAY['woman'],18,30); RAISE EXCEPTION 'ambiguous adult accepted'; EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'birth_date_required' THEN RAISE; END IF; END;
END $$;
SELECT set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000001',false);
DO $$ DECLARE s jsonb; BEGIN
 s:=public.dating_state();
 IF jsonb_array_length(s->'cards')<>1 OR s->'cards'->0->>'id'<>'79000000-0000-4000-8000-000000000002' THEN RAISE EXCEPTION 'reciprocal boundaries failed'; END IF;
 IF s->'cards'->0 ? 'min_age' OR s->'cards'->0 ? 'birth_date' THEN RAISE EXCEPTION 'preferences exposed'; END IF;
 BEGIN PERFORM 1 FROM public.dating_profiles; RAISE EXCEPTION 'raw profile accessible'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.dating_pair_eligible(auth.uid(),'79000000-0000-4000-8000-000000000002'); RAISE EXCEPTION 'helper exposed'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
 BEGIN PERFORM public.dating_send_message('79000000-0000-4000-8000-000000000002','unmatched'); RAISE EXCEPTION 'unmatched message'; EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'unavailable' THEN RAISE; END IF; END;
END $$;
SELECT public.dating_act('79000000-0000-4000-8000-000000000002','like');
SELECT set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000002',false);
DO $$ BEGIN IF jsonb_array_length(public.dating_state(NULL,'likes')->'cards')<>1 THEN RAISE EXCEPTION 'incoming like missing'; END IF; END $$;
SELECT public.dating_act('79000000-0000-4000-8000-000000000001','like');
SELECT public.dating_send_message('79000000-0000-4000-8000-000000000001','hello');
SELECT set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000001',false);
DO $$ BEGIN IF jsonb_array_length(public.dating_messages_get('79000000-0000-4000-8000-000000000002'))<>1 THEN RAISE EXCEPTION 'message missing'; END IF; END $$;
RESET ROLE;
INSERT INTO public.events(id,created_by,title) VALUES('79000000-0000-4000-9000-000000000001','79000000-0000-4000-8000-000000000005','Dating fixture event');
INSERT INTO public.rsvps(event_id,user_id) VALUES('79000000-0000-4000-9000-000000000001','79000000-0000-4000-8000-000000000001');
INSERT INTO public.user_follows(follower_id,following_id) VALUES('79000000-0000-4000-8000-000000000002','79000000-0000-4000-8000-000000000001');
SET ROLE anon;
SELECT set_config('request.jwt.claim.sub','',false);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.rsvps) THEN RAISE EXCEPTION 'anonymous attendee exposure'; END IF;
 IF (public.get_event_counts('79000000-0000-4000-9000-000000000001')->>'going_count')::int<>1 THEN RAISE EXCEPTION 'anonymous counts broken'; END IF;
 IF has_function_privilege('anon','public.get_friend_activity(uuid,integer,integer)','EXECUTE') THEN RAISE EXCEPTION 'anonymous feed exposed'; END IF;
 IF has_function_privilege('anon','public.dating_state(uuid,text)','EXECUTE') THEN RAISE EXCEPTION 'anonymous dating RPC exposed'; END IF;
END $$;
SET ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000002',false);
DO $$ BEGIN IF EXISTS(SELECT 1 FROM public.rsvps) THEN RAISE EXCEPTION 'default activity not private'; END IF;
 IF (public.get_friends_attending(auth.uid(),'79000000-0000-4000-9000-000000000001')->>'total')::int<>0 THEN RAISE EXCEPTION 'friend RPC leaked private attendance'; END IF;
 IF public.get_friend_activity('79000000-0000-4000-8000-000000000003')<>'[]'::jsonb THEN RAISE EXCEPTION 'impersonated feed'; END IF;
 END $$;
SELECT set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000001',false);
SELECT public.dating_set_activity_audience('matches');
SELECT set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000002',false);
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.rsvps) THEN RAISE EXCEPTION 'matched activity missing'; END IF; END $$;
SELECT public.dating_act('79000000-0000-4000-8000-000000000001','pass',true);
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM public.rsvps) THEN RAISE EXCEPTION 'activity visible after pass'; END IF;
 BEGIN PERFORM public.dating_send_message('79000000-0000-4000-8000-000000000001','after pass'); RAISE EXCEPTION 'message after pass'; EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'unavailable' THEN RAISE; END IF; END;
END $$;
SELECT public.dating_report('79000000-0000-4000-8000-000000000001','harassment','Fixture report');
SELECT set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000005',false);
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.rsvps) THEN RAISE EXCEPTION 'host roster broken'; END IF; END $$;
SELECT set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000003',false);
DO $$ BEGIN BEGIN PERFORM public.dating_admin_reports(); RAISE EXCEPTION 'nonstaff reports access'; EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'unauthorized' THEN RAISE; END IF; END; END $$;
SELECT set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000006',false);
DO $$ DECLARE r jsonb; BEGIN r:=public.dating_admin_reports(); IF jsonb_array_length(r)<>1 THEN RAISE EXCEPTION 'staff report missing'; END IF; PERFORM public.dating_moderate((r->0->>'id')::uuid,true); END $$;
SELECT set_config('request.jwt.claim.sub','79000000-0000-4000-8000-000000000001',false);
DO $$ BEGIN IF NOT(public.dating_state()->>'suspended')::boolean THEN RAISE EXCEPTION 'suspension missing'; END IF; END $$;
RESET ROLE;
